        payload = jwt.decode(authorization[7:], JWT_SECRET, algorithms=[JWT_ALGORITHM])
    except jwt.PyJWTError:
        raise HTTPException(status_code=401)
    user = session.get(User, int(payload["sub"]))
    if user is None:
        raise HTTPException(status_code=401)
    return user

